INSERT INTO `${table.prefix}node_desc` (node_id, description) VALUES ('dsth9iPoRTcZpy8xTQ', '{"type": "slate", "data": [{"type": "paragraph", "data": {"align": "alignLeft"}, "object": "block", "children": [{"text": "使用此看板，您可以一览所有视频项目的进展状态。跟踪视频需求，实时掌握每个项目的制作状态。"}]}], "render": "\u003cp\u003e使用此看板，您可以一览所有视频项目的进展状态。跟踪视频需求，实时掌握每个项目的制作状态。\u003c/p\u003e"}') ON DUPLICATE KEY UPDATE description = '{"type": "slate", "data": [{"type": "paragraph", "data": {"align": "alignLeft"}, "object": "block", "children": [{"text": "使用此看板，您可以一览所有视频项目的进展状态。跟踪视频需求，实时掌握每个项目的制作状态。"}]}], "render": "\u003cp\u003e使用此看板，您可以一览所有视频项目的进展状态。跟踪视频需求，实时掌握每个项目的制作状态。\u003c/p\u003e"}';
INSERT INTO `${table.prefix}node_desc` (node_id, description) VALUES ('dsteH98bsuEjJaxwUy', '{"type": "slate", "data": [{"type": "paragraph", "data": {"align": "alignLeft"}, "object": "block", "children": [{"text": "欢迎使用联系人看板！您可以在这里记录和管理所有联系人信息，包括公司、职位、联系方式等。"}]}], "render": "\u003cp\u003e欢迎使用联系人看板！您可以在这里记录和管理所有联系人信息，包括公司、职位、联系方式等。\u003c/p\u003e"}') ON DUPLICATE KEY UPDATE description = '{"type": "slate", "data": [{"type": "paragraph", "data": {"align": "alignLeft"}, "object": "block", "children": [{"text": "欢迎使用联系人看板！您可以在这里记录和管理所有联系人信息，包括公司、职位、联系方式等。"}]}], "render": "\u003cp\u003e欢迎使用联系人看板！您可以在这里记录和管理所有联系人信息，包括公司、职位、联系方式等。\u003c/p\u003e"}';
INSERT INTO `${table.prefix}node_desc` (node_id, description) VALUES ('dst9JQFqb5Jew0KQSY', '{"type": "slate", "data": [{"type": "paragraph", "data": {"align": "alignLeft"}, "object": "block", "children": [{"text": "此看板用于管理单个项目。您可以根据项目需求自定义此看板：添加字段、子任务、自动化、仪表盘等功能！"}]}], "render": "\u003cp\u003e此看板用于管理单个项目。您可以根据项目需求自定义此看板：添加字段、子任务、自动化、仪表盘等功能！\u003c/p\u003e"}') ON DUPLICATE KEY UPDATE description = '{"type": "slate", "data": [{"type": "paragraph", "data": {"align": "alignLeft"}, "object": "block", "children": [{"text": "此看板用于管理单个项目。您可以根据项目需求自定义此看板：添加字段、子任务、自动化、仪表盘等功能！"}]}], "render": "\u003cp\u003e此看板用于管理单个项目。您可以根据项目需求自定义此看板：添加字段、子任务、自动化、仪表盘等功能！\u003c/p\u003e"}';
INSERT INTO `${table.prefix}node_desc` (node_id, description) VALUES ('dstDNqjqhluX175gAH', '{"type": "slate", "data": [{"type": "paragraph", "data": {"align": "alignLeft"}, "object": "block", "children": [{"text": "此看板非常适合跨团队和部门追踪工作效率、产出质量和员工满意度。评分汇总可用于辅助决策，指导重点资源的投入方向。"}]}], "render": "\u003cp\u003e此看板非常适合跨团队和部门追踪工作效率、产出质量和员工满意度。评分汇总可用于辅助决策，指导重点资源的投入方向。\u003c/p\u003e"}') ON DUPLICATE KEY UPDATE description = '{"type": "slate", "data": [{"type": "paragraph", "data": {"align": "alignLeft"}, "object": "block", "children": [{"text": "此看板非常适合跨团队和部门追踪工作效率、产出质量和员工满意度。评分汇总可用于辅助决策，指导重点资源的投入方向。"}]}], "render": "\u003cp\u003e此看板非常适合跨团队和部门追踪工作效率、产出质量和员工满意度。评分汇总可用于辅助决策，指导重点资源的投入方向。\u003c/p\u003e"}';
INSERT INTO `${table.prefix}node_desc` (node_id, description) VALUES ('dstaCx7dxRr5sd4Uxd', '{"type": "slate", "data": [{"type": "paragraph", "data": {"align": "alignLeft"}, "object": "block", "children": [{"text": "此看板按优先级顺序统一追踪和管理所有创意需求（设计+文案），帮助高层决策者和申请人随时了解各地区或板块的项目进展。"}]}], "render": "\u003cp\u003e此看板按优先级顺序统一追踪和管理所有创意需求（设计+文案），帮助高层决策者和申请人随时了解各地区或板块的项目进展。\u003c/p\u003e"}') ON DUPLICATE KEY UPDATE description = '{"type": "slate", "data": [{"type": "paragraph", "data": {"align": "alignLeft"}, "object": "block", "children": [{"text": "此看板按优先级顺序统一追踪和管理所有创意需求（设计+文案），帮助高层决策者和申请人随时了解各地区或板块的项目进展。"}]}], "render": "\u003cp\u003e此看板按优先级顺序统一追踪和管理所有创意需求（设计+文案），帮助高层决策者和申请人随时了解各地区或板块的项目进展。\u003c/p\u003e"}';
INSERT INTO `${table.prefix}node_desc` (node_id, description) VALUES ('dstvSQ9PNqdpMkQGc9', '{"type": "slate", "data": [{"type": "paragraph", "data": {"align": "alignLeft"}, "object": "block", "children": [{"text": "使用此看板可创建表单，用于收集内部需求申请，并实时跟踪申请状态。"}]}], "render": "\u003cp\u003e使用此看板可创建表单，用于收集内部需求申请，并实时跟踪申请状态。\u003c/p\u003e"}') ON DUPLICATE KEY UPDATE description = '{"type": "slate", "data": [{"type": "paragraph", "data": {"align": "alignLeft"}, "object": "block", "children": [{"text": "使用此看板可创建表单，用于收集内部需求申请，并实时跟踪申请状态。"}]}], "render": "\u003cp\u003e使用此看板可创建表单，用于收集内部需求申请，并实时跟踪申请状态。\u003c/p\u003e"}';
INSERT INTO `${table.prefix}node_desc` (node_id, description) VALUES ('dstbP1faLDQdN2t8ZW', '{"type": "slate", "data": [{"type": "paragraph", "data": {"align": "alignLeft"}, "object": "block", "children": [{"text": "欢迎使用潜在客户看板！您可以在这里存储和管理所有潜在客户信息，并与工作区的其他数据关联，确保数据始终有上下文。"}]}], "render": "\u003cp\u003e欢迎使用潜在客户看板！您可以在这里存储和管理所有潜在客户信息，并与工作区的其他数据关联，确保数据始终有上下文。\u003c/p\u003e"}') ON DUPLICATE KEY UPDATE description = '{"type": "slate", "data": [{"type": "paragraph", "data": {"align": "alignLeft"}, "object": "block", "children": [{"text": "欢迎使用潜在客户看板！您可以在这里存储和管理所有潜在客户信息，并与工作区的其他数据关联，确保数据始终有上下文。"}]}], "render": "\u003cp\u003e欢迎使用潜在客户看板！您可以在这里存储和管理所有潜在客户信息，并与工作区的其他数据关联，确保数据始终有上下文。\u003c/p\u003e"}';
INSERT INTO `${table.prefix}node_desc` (node_id, description) VALUES ('fodgHZt1s5CvY', '{"type": "slate", "data": [{"type": "paragraph", "data": {"align": "alignLeft"}, "object": "block", "children": [{"text": "跨多个团队和部门进行规划、追踪和管理复杂项目始终充满挑战。使用此模板，您可以更好地进行项目管理，包括任务管理、进度追踪、团队协作等。"}]}], "render": "\u003cp\u003e跨多个团队和部门进行规划、追踪和管理复杂项目始终充满挑战。使用此模板，您可以更好地进行项目管理，包括任务管理、进度追踪、团队协作等。\u003c/p\u003e"}') ON DUPLICATE KEY UPDATE description = '{"type": "slate", "data": [{"type": "paragraph", "data": {"align": "alignLeft"}, "object": "block", "children": [{"text": "跨多个团队和部门进行规划、追踪和管理复杂项目始终充满挑战。使用此模板，您可以更好地进行项目管理，包括任务管理、进度追踪、团队协作等。"}]}], "render": "\u003cp\u003e跨多个团队和部门进行规划、追踪和管理复杂项目始终充满挑战。使用此模板，您可以更好地进行项目管理，包括任务管理、进度追踪、团队协作等。\u003c/p\u003e"}';

